-- Yuumi (UNL 056) is the same card as the existing Summoner Skirmish entries, so drop my duplicate and fix those. Jayce, Yone and the Vendetta Vault token. Safe to run more than once.
delete from promo_items where id = 'item-10665';
update promo_items set data = data || $j${"cn": "056", "evl": "Unleashed Summoner Skirmish, May 2026 organized play event", "inf": "Promo card from the Unleashed Summoner Skirmish organized play event, May 2026 (UNL 056/219 P). Also exists in English; the language links show the other versions.", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/yuumi-magical-cat-unl-ch-item-10665.webp"}$j$::jsonb where id = 'item-10247';
update promo_items set data = data || $j${"cn": "056", "evl": "Unleashed Summoner Skirmish, May 2026 organized play event", "inf": "Promo card from the Unleashed Summoner Skirmish organized play event, May 2026 (UNL 056/219 P). Also exists in English; the language links show the other versions."}$j$::jsonb where id = 'item-10257';
update promo_items set data = data || $j${"nm": "Jayce - Man of Progress (Promo)", "ev": "China - Spiritforged launch celebration and prerelease events (售前现开)\nNexus Nights - China\nSummoner Skirmishes - China", "evl": "Spiritforged launch celebration and prerelease events at local game stores in China, December 12 to 28, 2025. Players who registered through the Riftbound WeChat mini-program and took part received the stamped promo. Leftover celebration promos also went out at Nexus Nights (符文之夜), and Summoner Skirmishes (符文竞技) were held after launch.", "inf": "Chinese promo of Jayce - Man of Progress (SFD 084/221, promo stamp), given out at the Spiritforged launch celebration and prerelease events in China in December 2025. The English promo version is listed under the same name, so the language links connect them."}$j$::jsonb where id = 'item-10666';
update promo_items set data = data || $j${"nm": "Yone - Blademaster (Spiritforged Pre-Rift)", "ev": "Spiritforged Pre-Rift events", "evl": "Every player at a Spiritforged Pre-Rift event received a sealed Pre-Rift Player Kit: a 15-card mini deck, 5 booster packs and 1 guaranteed Pre-Rift promo card, which was this stamped Yone.", "inf": "English Pre-Rift promo of Yone - Blademaster (SFD 116/221, promo stamp), the guaranteed promo in the Spiritforged Pre-Rift Player Kit."}$j$::jsonb where id = 'item-10663';
insert into promo_items (id, r, data)
select 'item-10674', 10674, $j${"r": 10674, "id": "item-10674", "cat": "PROMO", "nm": "Tentacle / Shadow Clone Token (Double-Sided)", "la": "English", "ev": "Vendetta Vault", "se": "VEN", "ty": "Card", "cn": "N/A", "ra": "Token", "do": "N/A", "tg": "Token\nDouble-Sided\nVendetta Vault", "fo": true, "tn": false, "me": false, "nn": false, "bm": false, "pw": false, "pt": "", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/tentacle-shadow-clone-token-vendetta-vault-en-item-10674.webp", "inf": "Double-sided Vendetta token (Tentacle on one side, Shadow Clone on the other), found only in the Riftbound: Vendetta Vault bundle."}$j$::jsonb || jsonb_build_object('st', coalesce((select data->>'st' from promo_items where upper(data->>'st')='NEED' limit 1),'NEED'))
where not exists (select 1 from promo_items where id = 'item-10674');
